# 3. CREATE WORKBOOK
# ─────────────────────────────────────────────
def create_workbook():
    wb = openpyxl.Workbook()

    # --- TestPlan sheet ---
    ws_tp = wb.active
    ws_tp.title = "TestPlan"

    header_font = Font(name="Calibri", bold=True, size=11, color="FFFFFF")
    header_fill = PatternFill(start_color="4472C4", end_color="4472C4", fill_type="solid")
    header_align = Alignment(horizontal="center", vertical="center", wrap_text=True)
    cell_align = Alignment(vertical="top", wrap_text=True)
    thin_border = Border(
        left=Side(style="thin"), right=Side(style="thin"),
        top=Side(style="thin"), bottom=Side(style="thin")
    )

    # Write headers
    for col_idx, col_name in enumerate(COLUMNS, 1):
        cell = ws_tp.cell(row=1, column=col_idx, value=col_name)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = header_align
        cell.border = thin_border

    # Write data rows
    for row_idx, entry in enumerate(final_json, 2):
        for col_idx, col_name in enumerate(COLUMNS, 1):
            val = entry.get(col_name, "")
            cell = ws_tp.cell(row=row_idx, column=col_idx, value=val)
            cell.alignment = cell_align
            cell.border = thin_border

    # Column widths
    col_widths = {
        "Index": 8, "SS / Module": 14, "Feature": 22, "Test Case Name": 30,
        "Test Description": 60, "Meta Test Description": 60, "Speed": 10,
        "Mode": 12, "Memory Start Offset": 18, "Memory End Offset": 18,
        "Remarks": 50, "Test Steps / Procedure": 60,
        "Meta Test Steps / Procedure": 60, "Impacted Registers": 40,
        "Meta Impacted Registers": 50, "Validation / Acceptance Criteria": 60,
        "Meta Validation / Acceptance Criteria": 60,
        "Code Generation (Required / Not)": 18, "Meta Headers": 50,
        "Meta Macros": 40, "Meta Arrays": 60
    }
    for col_idx, col_name in enumerate(COLUMNS, 1):
        letter = get_column_letter(col_idx)
        ws_tp.column_dimensions[letter].width = col_widths.get(col_name, 30)

    # Freeze first row
    ws_tp.freeze_panes = "A2"

    # --- MetaData sheet (very hidden) ---
    ws_md = wb.create_sheet(title="MetaData")
    ws_md.sheet_state = "veryHidden"
    ws_md.cell(row=1, column=1, value="JSON_DATA")
    json_str = json.dumps(final_json, indent=2, ensure_ascii=False)
    # Split JSON across rows (max ~32000 chars per cell)
    CHUNK = 32000
    for i, start in enumerate(range(0, len(json_str), CHUNK), 2):
        ws_md.cell(row=i, column=1, value=json_str[start:start+CHUNK])

    # Save
    local_path = FILENAME
    wb.save(local_path)
    print(f"[OK] Workbook saved locally: {local_path}")
    return local_path

# ─────────────────────────────────────────────
# 4. PUSH TO GITHUB
# ─────────────────────────────────────────────
def push_to_github(local_path):
    if not GITHUB_TOKEN:
        print("[WARN] GITHUB_TOKEN not set. Skipping push.")
        print(f"       Set env var GITHUB_TOKEN and re-run, or manually upload:")
        print(f"       {local_path} -> {GITHUB_PATH}")
        return None, None

    with open(local_path, "rb") as f:
        content_b64 = base64.b64encode(f.read()).decode("ascii")

    url = f"https://api.github.com/repos/{OWNER}/{REPO}/contents/{GITHUB_PATH}"
    headers = {
        "Authorization": f"token {GITHUB_TOKEN}",
        "Accept": "application/vnd.github.v3+json"
    }

    # Check if file already exists (to get SHA for update)
    resp = requests.get(url, headers=headers, params={"ref": BRANCH})
    sha = resp.json().get("sha") if resp.status_code == 200 else None

    payload = {
        "message": f"Add GPIO TestPlan Excel: {FILENAME} (IST {now_ist.strftime('%Y-%m-%d %H:%M:%S')})",
        "content": content_b64,
        "branch": BRANCH
    }
    if sha:
        payload["sha"] = sha

    resp = requests.put(url, headers=headers, json=payload)
    if resp.status_code in (200, 201):
        data = resp.json()
        commit_sha = data.get("commit", {}).get("sha", "unknown")
        html_url = data.get("content", {}).get("html_url", "unknown")
        print(f"[OK] Pushed to GitHub successfully.")
        print(f"     Commit SHA : {commit_sha}")
        print(f"     GitHub URL : {html_url}")
        return commit_sha, html_url
    else:
        print(f"[ERROR] GitHub push failed: {resp.status_code}")
        print(resp.text)
        return None, None

# ─────────────────────────────────────────────
# 5. MAIN
# ─────────────────────────────────────────────
if __name__ == "__main__":
    print("="*60)
    print("GPIO TestPlan Excel Generator — Fallback Automation")
    print(f"IST Timestamp: {now_ist.strftime('%Y-%m-%d %H:%M:%S')}")
    print(f"Output File  : {FILENAME}")
    print(f"GitHub Path  : {GITHUB_PATH}")
    print("="*60)

    local_path = create_workbook()
    commit_sha, html_url = push_to_github(local_path)

    print("\n" + "="*60)
    print("FINAL STATUS:")
    print(json.dumps({
        "status": "SUCCESS" if commit_sha else "LOCAL_ONLY",
        "execution_mode": "Fallback Automation",
        "output_file_path": GITHUB_PATH,
        "local_file": local_path,
        "github_url": html_url or "NA",
        "commit_sha": commit_sha or "NA"
    }, indent=2))
    print("="*60)
